# Description: A multimodal optimization benchmark function with multiple global minima arranged in a grid pattern, combined with a deceptive quadratic basin to test optimization algorithms' ability to escape local optima and find global minima.
# Code:
```python
import numpy as np

class MultimodalGridBenchmark:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        # Scale input to [-5, 5] domain
        x = np.clip(x, -5.0, 5.0)

        # Create grid of global minima at positions (±2, ±2, ±2, ...)
        grid_minima = []
        for i in range(self.dim):
            if i % 2 == 0:
                grid_minima.append([-2, 2])
            else:
                grid_minima.append([-2, 2])

        # Calculate distance to nearest grid minimum
        min_dist = float('inf')
        for i in range(len(grid_minima)):
            for j in range(len(grid_minima[i])):
                if i < len(x):
                    dist = abs(x[i] - grid_minima[i][j])
                    if dist < min_dist:
                        min_dist = dist

        # Add deceptive quadratic basin term that pulls towards origin
        basin_term = 0.1 * np.sum(x**2)

        # Combine terms with a scaling factor
        return min_dist + basin_term
```

# Description: A multimodal optimization benchmark with multiple global minima arranged in a grid pattern combined with a deceptive quadratic basin, using sinusoidal perturbations to increase landscape complexity and challenge optimization algorithms' ability to escape local optima.
# Code:
```python
import numpy as np

class MultimodalGridBenchmark:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        # Scale input to [-5, 5] domain
        x = np.clip(x, -5.0, 5.0)

        # Grid of global minima at positions (±2, ±2, ±2, ...)
        grid_minima = []
        for i in range(self.dim):
            if i % 2 == 0:
                grid_minima.append([-2, 2])
            else:
                grid_minima.append([-2, 2])

        # Calculate distance to nearest grid minimum
        min_dist = float('inf')
        for i in range(len(grid_minima)):
            for j in range(len(grid_minima[i])):
                if i < len(x):
                    dist = abs(x[i] - grid_minima[i][j])
                    if dist < min_dist:
                        min_dist = dist

        # Add sinusoidal perturbations to increase landscape complexity
        sin_term = 0.5 * np.sum(np.sin(3.0 * x))

        # Add deceptive quadratic basin term that pulls towards origin
        basin_term = 0.1 * np.sum(x**2)

        # Combine all terms
        return min_dist + basin_term + sin_term
